-- Descripciones de los platos de la carta (ES, EN y FR).
-- Se rellenaron el 28/10/2026 en el proyecto viejo (jeamoczmbfsnwkfjxcyo) después
-- de copiar los datos a demo/producción; esta migración las lleva a los nuevos.
-- Solo datos: actualiza por id + nombre, así que un plato renombrado o que no
-- exista se salta sin error. Se puede ejecutar más de una vez.
--
-- Antes de tocar nada guarda los valores actuales en una tabla de respaldo.
-- Para deshacer:
--   update public."Platos" p set descripcion = b.descripcion,
--     descripcion_en = b.descripcion_en, descripcion_fr = b.descripcion_fr
--   from public._respaldo_platos_descripciones_20261029 b where b.id = p.id;
--   drop table public._respaldo_platos_descripciones_20261029;

begin;

create table if not exists public._respaldo_platos_descripciones_20261029 as
  select id, nombre, descripcion, descripcion_en, descripcion_fr from public."Platos";
alter table public._respaldo_platos_descripciones_20261029 enable row level security;

update public."Platos" set descripcion = NULL, descripcion_en = 'Tomalo', descripcion_fr = 'Tomalo' where id = '00419392-705c-4c68-92b1-431fa9b639ae' and nombre = 'Almeja gallega plancha';
